// registry.js - the module itself is the well-known object
const entries = new Map();
export function register(name, impl) {
  if (entries.has(name)) throw new Error(`duplicate registration: ${name}`);
  entries.set(name, impl);
}
export function lookup(name) {
  const impl = entries.get(name);
  if (impl === undefined) throw new Error(`unknown entry: ${name}`);
  return impl;
}
